import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        t = int(t_str)
    except StopIteration:
        return

    for _ in range(t):
        try:
            n_str = next(iterator)
            if n_str == n_str[::-1]:
                print("wins")
            else:
                print("loses")
        except StopIteration:
            break

if __name__ == "__main__":
    solve()
